      "transition": "重心由训练基建 → 推理规模化：推理毛利更高、需求更持久，是下一阶段主线。",
      "narrative": "四大 hyperscaler 2026Q3 单季 capex 合计 $2087亿（+84% YoY / +22% QoQ），按最新指引中值全年约 $7300亿，较二季报后的 $7325亿略降——降的是微软（第三方算力交付延迟，CY26 由 $1750亿降至 $1700亿），不是需求。真正的转折在现金流：Alphabet Q3 FCF −$91亿、财报后单日跌约 11% 创史上最大单日跌幅；Meta Q3 FCF −$21亿；亚马逊 TTM FCF −$424亿。\n\n11 月首周把这条逻辑一次性定价了两遍。11/4 是跷跷板：道指 +3.03%(+1569 点)、微软 +6.7%、亚马逊 +6.1%、苹果 +5.3%，资金从算力链撤向现金流稳定的巨头；同日费半 −3.1%、美光 −7%、Marvell −7.1%。11/5 转为无差别杀跌：纳指 −3%、费半盘中 −8%，美光 −16%、AMD 与 Lumentum 系光模块 −10% 以上、Coherent −9%、SK海力士 −8%、英伟达 −8.6%。两天合起来不是 AI 叙事破裂，而是「谁在付账单」的重新排序——有自由现金流的分母端被买入，靠 capex 输血的分子端被卖出。\n\n触发这条链的外生变量是 11/3 中期选举：民主党横扫两院，得州州长由承诺上任即暂停数据中心审批的 Hinojosa 当选。高盛测算州/地方层面的暂停令可波及约 45% 的规划新增产能(得州单独约 25-27%)；大摩则指出真正约束项目的杠杆——电网并网、大负荷电价设计、选址、税收减免——几乎全在州监管委员会与县委员会手里，得州州长可通过多个监管机构介入审批，大量项目面临大幅延期。联邦层面反而约束有限：相关立法仍需参议院 60 票并要越过否决权。\n\n第二层变量是存储涨价的周期信号转弱：业绩并不差的希捷 −8%、闪迪 −8%、西数 −6.8%、美光 −7% 在同一天被抛售，杀的是「涨价驱动」这个定价前提；国内侧同源验证是新易盛 Q3 营收环比 −13%、归母净利环比 −19%、经营现金流转负。存储与光模块既是 AI 服务器上游，需求又高度绑定云厂商 capex 强度，一旦扩产放缓，HBM/DRAM/光模块的需求预期会同步下修。\n\n因此当前主要矛盾已从「算力/电力瓶颈」升级为「政治审批风险 × 涨价周期见顶」的双杀，资金开始按自由现金流质量分层，而非按 AI 敞口大小分层。\n\n11/6 给出两个反向证据，需要分开写而不是合成一句。其一，季报兑现的分子端被立刻买回：费半 11/5 收 −12.3%，11/6 盘中 +4.0%，Coherent +11.1%、AMD +9.3%、Vistra +8.7%、Oklo +18.7%——11/5 的无差别杀跌更像流动性与情绪，不是对基本面的重定价。其二，涨价见顶只在存储端成立、在光互联端不成立：同为 11/6，韩系存储在亚洲时段补跌(SK海力士 −9.5%、三星 −7.6%，在补 11/5 的美股跌幅)，而 Coherent Q1 FY27 交出 datacom +79%、毛利率 +254bp、并把「non-GAAP 毛利率 >45%」写进 2028 日历年路线图，Lumentum 上季 +136% 亦同向。故「涨价周期见顶」应限定为存储(HBM/DRAM 价格弹性)，光互联当前仍是量价齐升。\n\n审批风险的第一个检验样本(VST，11/6)既没证伪也没证实：2027 指引 $77-85亿 adj EBITDA、中值较 2026 高 11%，且约 98% 预期发电量已套保——但 VST 剩余得州敞口本就小(Cogentrix 5,496MW 中得州仅 11%)，用它证明得州风险解除属无效推断。真正的检验在 CEG(11/9 盘前，PJM 核电+Calpine 并表口径)与 CRWV(11/10 盘前，得州新建交付的直接对象)；截至本表更新这两家均未披露。",
