    "method": "信号分级框架：主导矛盾(数据自动选原型) / 领先确认(触发情景转换的硬指标) / 交叉验证(验证涨势广度与背离)。主导矛盾由 gen_datajs.py 依据实时复合指标(债股背离/通胀压力/增长/流动性/广度)从 archetypes[] 自动选出原型；manualOverride=true 时改回使用下方 dominant 策展文案。锚点状态实时计算；序列缺失回退策展。历史沿革(压缩)：2026-08-12 纳入经济 regime(滞胀组合)、利率熊陡 47bp、非农 -23K；08-19 核心 CPI 环比 +0.22%(cpi_accel 转 on)、流动性转 tight；08-27 disagreement 转 F、breadth 转 broad；09-03 yields_high/curve_bear_steep/nfp_negative 转 on；09-10 nfp_negative 与 yields_high 双双转 off(差 1bp)、liquidity 转 neutral；09-17 yields_high 转 on(4.97 破 4.90)、credit_widen 转 on(HY 2.71)、liquidity 转 easy；09-24 FOMC(9/15-16)加息至 3.75-4.00% 但三项锚同时转 off，activeScenario 首次回落为「未达成」；10-08 主导矛盾由 inflation_reignite 切换为新增原型 stagflation_squeeze；10-15 锚点与复合指标均无一转态；10-22 disagreement 由 T 转 F(股债同跌)，bond_vs_equity 掉到 0/1；10-29 新增 equity_credit_split(3/3)并以「股债双涨 + 信用走阔」主导一周；11-05 见下。 2026-11-05 刷新(第 5 版；数据截点：FRED 2026-11-02(利率/信用/HY)、美股 11-03 收盘、商品/汇率/黄金 11-03、CFTC 11-04)：(1) 主导矛盾由 equity_credit_split 交回 **stagflation_squeeze(2/2 全命中)**。切换原因不是本档变强，而是上一档的一条腿断了：equity_credit_split 的 eqUp 由 T 转 F(SPX 月 +0.51%→**-2.35%**)，3/3 掉到 **2/3**、失去 full 标记；按 _arch_rank 的「全命中优先」，主导权自动交回 2/2 的滞胀档。这正是 10-29 设计该档时写下的预期行为(任一条件失效即让位)，不是人工裁决。(2) **锚点本期两项转态**：equity_up on→**off**、equity_down off→**on**——同一组数值的两面(SPX 7,541.40 低于 60 日均值 7,699.93 达 158.5 点/2.06%)。10 条锚现为 on **3** 条(equity_down / cpi_accel / credit_widen)、off 5 条(yields_high / equity_up / nfp_negative / crypto_divergence / curve_bear_steep)、curated 2 条。(3) **情景层出现六期以来第一次达成**：growth_weak(equity_down + credit_widen)**2/2 全命中**，activeScenario 由连续六期「未达成」转为 **growth_weak**。它与主导档不冲突——滞胀的「增长弱」腿正是这两条构成；但档↔情景映射指向通胀腿(inflation_reignite 1/2 未达成)，所以 scenarioMeta.sameSourceAsDominant=false 属预期行为，不是两层判断打架。(4) **未增删原型(8 → 8)、未改任何 trigger/priority/rank、未动 gen_datajs.py 判定逻辑**。本周组合(inflation=high + growth=weak，且两条腿同时成立)落在滞胀档既有覆盖域内，故不新增槽位；上周新档只失去一条腿、已按设计降为后备，说明它捕获的是「股债双涨 + 信用走阔」这一更窄形态。★ 下一个可能需要新槽位的是「股跌 + 债也跌 + 信用走阔」({yldUp:T, eqUp:F, creditStress:T})，本周**不是**这个形态(10Y 月 -33bp)，故留作观察项而非预建。(5) 修正 macro_signal_propose.py 的排序键：原实现只用「命中条数 + priority」，不吃 full/ratio/rank，本期因此把 2/3 的 equity_credit_split 报成主导(与面板实际的 stagflation_squeeze 不一致)。现改为与 gen_datajs._arch_rank 同构的 (full, matched, ratio, priority, -rank)，并把 calm_goldilocks 排除出主竞赛。此修改只影响辅助脚本的提示文本，不触碰面板判定。(6) 已知数据缺陷(引用时逐条披露)：① fed.policyTable 写「2026-11-03 加息 25bp」——实际政策区间自 09-17 起即为 3.75-4.00%、IORB 3.90% 月变 **0bp**、10/27-28 会议按兵不动；该日期随数据日漂移是长期缺陷(**第 9 次记录**)；② tradeRadar.policy_gap 仍写「非农已转负」而后文数据为 +29K；③ recession 面板 3M-10Y 的 meaning 写「当前 +1bp」而 value 0.86；④ 制造业/服务业 PMI 55.7/55.0 仍是 **2026-06 vintage(stale 156 天)**，不能作为当期产出证据；⑤ 9 月核心 PCE 与超级核心**本期已落地**(3.12% / 3.60%)，此前「8 月 vintage」的披露可以撤销。",
