        "text": "equity_up 由 on 转 **off**、equity_down 由 off 转 **on**，是本期的机械转态；但真正要判断的是**这次下跌属于哪一类**。三条证据指向「分子」而不是「分母」：① 分母端同期在松——10Y TIPS 月 **-26bp**、TLT 月 **+5.19%**、ACM 期限溢价 0.9857→0.9089，若这是贴现率冲击，长债应当同跌；② 跌幅集中在长久期与高估值端——SOX 月 **-19.53%**、NDX 月 **-9.32%**，而 DJI 月 **+1.01%**(唯一为正)，这是典型的「分子修正 + 防御轮动」，不是无差别抛售；③ 信用同向恶化——HY 月 +33bp 至 3.43%、B 级月 +51bp、SOFR-IORB +5bp，融资条件在收紧。★ 上周本栏写的是「股票把实际利率回落读成贴现率救赎，信用读成基本面在坏，两边不可能同时对很久」，本期裁决出来了：**股票让步**。SPX 7,541.40 收在 60 日均值 7,699.93 下方 158.5 点，四周内余量走完 +140.7 → +26.45 → +16.97 → **-158.5** 的完整穿越。偏「跌到位」的一侧：VIX 20.83 只是刚站上 20、MOVE 99.97 仍在 100 下方、SKEW 150.01 没有极端化，波动率结构还不像系统性事件；广度 25.6 已在低位，反向修复的空间存在。偏「刚开始」的一侧：广度 33 只样本仅 3 只站上 50 日均值、**0 只创新高**，强弱两端同步下跌(高分组 -9.58%、低分组 -18.92%)，这是「无处可躲」而不是「轮动」。裁决点：SPX 能否收回 7,699.93(收复则 equity_down 转 off、growth_weak 情景从 2/2 掉回 1/2)；以及 HY 是否站住 3.4——若信用在股票反弹时仍走阔，说明分子端的问题没解决。",
