        "text": "credit_widen 锚维持 on，但内部结构本期第二次翻转，这次的方向与上周相反。HY OAS 3.43%(月 +33bp、周 +13bp、99 分位)，B 级 **3.63%**(月 **+51bp**、周 +27bp、99 分位)——B 层重新快于指数本身(上周是 +36 vs +37，B 层落后)；CCC 13.19%(月 +117bp、半年 +388bp，但**周线 -26bp**、日 -8bp，是三周来第一次周线回落)。而 IG 0.94%(+9bp)、BBB 1.17%(+13bp)、BB 2.06%(+15bp) 仍只在个位数到十几 bp 的区间。合起来是一个此前没出现过的组合：**最弱端开始回补、中间层在加速、高等级不动**。★ 这个组合的性质需要谨慎：它既可以被读成「CCC 已经跌够、风险向 B 传导」(偏空)，也可以被读成「CCC 的极端估值在被买回、B 层在追赶补跌」(偏多)，两者的区别在后续两周——若 B 继续走阔而 CCC 保持回落，是压力沿阶梯上移、下一站是 BB/BBB(这才是系统性事件的开端)；若 B 与 CCC 同时收敛，则本周只是一次仓位再平衡。偏空的一侧还有两条：credit 面板「资本配置」评分 88.5「耗尽」，CCC/HY 利差 976bp(月 +84bp)、BBB/IG 23bp；杠杆贷款指数 98.3 逼近 97 的预警线。偏多的一侧：HYG 月 **0.0%**、LQD 月 +1.86%——ETF 层面并没有崩，跌幅集中在 OAS 定价而非现券抛售。口径限制：违约率 TTM 1.9% 是 2026-04 vintage、滞后半年，不能用来否认当期利差，也不能用来预测当期违约。观察：B 是否连续两期快于指数、BBB 是否被带进来(1.17%)、CCC 周线回落能否延续到月线。",
